pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _minSum) internal {
        try c.SetMinSum(_minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        bool reverted;
        try c.Initialized() { reverted = false; } catch { reverted = true; }
        uint256 minSumAfter;
        try c.MinSum() returns (uint256 __r) { minSumAfter = __r; } catch { return; }
        assertTrue(!reverted && minSumAfter == minSumBefore);
    }

    function testFuzz_run(uint256 _minSum) public {
        _run(_minSum);
    }

    receive() external payable {}
}
